```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, span_name, count(*), approx_quantile(duration,0.5)/1e6, approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE span_name='rate.Rate/GetRates' GROUP BY 1,2,3",
          "claim": "search's client span to rate has median 1799ms (normal 3.3ms), while rate's own server span stays about 0.13ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.trace_id, round(c.duration/1e6,1) client_ms, round(s.duration/1e6,3) server_ms, round((epoch_ms(s.time)-epoch_ms(c.time)),1) start_offset_ms, round((epoch_ms(c.time)+c.duration/1e6)-(epoch_ms(s.time)+s.duration/1e6),1) end_gap_ms FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.service_name='rate' WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' ORDER BY c.time",
          "claim": "rate's server span starts about 1.4–1.6s after search's client span starts, and returns late; the delay is in transit, not in rate."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='search' AND span_name='search.Search/Nearby') GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Inside slow search traces, geo calls stay ~0.1–0.4ms while only the search→rate call takes ~1.8s."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name IN ('frontend','search') AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY 1,2 ORDER BY 1,2",
          "claim": "frontend's HTTP /hotels p95 is about 2557ms, tracking the search.Search/Nearby call (~1.8s median) it waits on."
        }
      ]
    }
  ]
}
```

